@Composable
fun ScheduledDateRow(
    scheduledDate: LocalDate?,
    onPickDate: () -> Unit,
    onClearDate: () -> Unit
) {
    Row(
        modifier = Modifier.fillMaxWidth(),
        horizontalArrangement = Arrangement.SpaceBetween,
        verticalAlignment = Alignment.CenterVertically
    ) {
        Column(modifier = Modifier.weight(1f)) {
            Text(stringResource(R.string.set_for_later_label), fontWeight = FontWeight.SemiBold, fontSize = 14.sp, color = MaterialTheme.colorScheme.onSurface)
            Text(
                scheduledDate?.let { stringResource(R.string.hidden_until_date, it.toString()) } ?: stringResource(R.string.today_starts_right_away),
                fontSize = 11.sp,
                color = MaterialTheme.colorScheme.onSurface.copy(alpha = 0.5f)
            )
        }
        if (scheduledDate != null) {
            IconButton(onClick = onClearDate) {
                Icon(Icons.Filled.Close, contentDescription = stringResource(R.string.clear_date_content_description), modifier = Modifier.size(18.dp))
            }
        }
        OutlinedButton(
            onClick = onPickDate,
            shape = RoundedCornerShape(8.dp),
            contentPadding = PaddingValues(horizontal = 16.dp, vertical = 6.dp)
        ) {
            Text(if (scheduledDate == null) stringResource(R.string.pick_date_button) else stringResource(R.string.change_button), fontWeight = FontWeight.Bold)
        }
    }
}
